function referencedColumn(tableName: string, columnName: string): AnyPgColumn {
	const table = tablesByName.get(tableName);
	const column =
		table &&
		Object.values(getColumns(table)).find(
			(column) => column.name === columnName,
		);
	if (!column)
		throw new Error(
			"Missing generated foreign key column: " + tableName + "." + columnName,
		);
	return column;
}
